function chainProxies(proxyList) {
  let currentProxy = proxyList[0];
  for (let i = 1; i < proxyList.length; i++) {
    currentProxy = new Proxy(currentProxy, {
      connect: (target, request, proxyArgs) => {
        return new Promise((resolve, reject) => {
          fetch(request, proxyArgs)
            .then(response => resolve(response))
            .catch(error => reject(error));
      }
    });
  }
  return currentProxy;
}
```

